import logging
import uuid

logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def place_order(self, user: str, item: str, quantity: int, is_admin: bool = False) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self.stock.reserve(item, quantity)
        except Exception as exc:
            ref = uuid.uuid4().hex
            logger.error(
                "Unexpected error while placing order (user=%r, item=%r, quantity=%r, ref=%s)",
                user, item, quantity, ref,
                exc_info=True,
            )
            if is_admin:
                text = (
                    f"An unexpected error occurred: {type(exc).__name__}: {exc}. "
                    f"Reference code: {ref}"
                )
            else:
                text = (
                    "An unexpected error occurred while placing your order. "
                    f"Please contact support with reference code: {ref}"
                )
            return 500, text

        return 200, (
            f"Order confirmed: {quantity} x {item!r} reserved "
            f"(reservation id: {reservation_id})."
        )
